func scipSymbol(header SnapshotHeader, projectVersion string, record SymbolRecord) string {
	if record.Local {
		// A callable defined inside another function cannot be referenced from
		// outside its document, and SCIP has a form that says so: `local <id>`,
		// scoped to the Document it appears in. Giving one a package-scoped
		// global symbol invites a consumer to merge two unrelated closures from
		// different documents that happen to share a name, or to link a
		// reference across a boundary the language does not have.
		return "local " + shortDigest(record.ID)
	}
	name := scipFirstNonEmpty(record.Name, record.QualifiedName, "symbol")
	return scipSymbolPrefix(header, projectVersion, record.FilePath) + scipDescriptor(name, record.Kind, shortDigest(record.ID))
}

