     1	package sem
     2	
     3	import (
     4		"encoding/json"
     5		"strings"
     6	)
     7	
     8	// ManifestReader reads one repo-root manifest by name and reports whether it
     9	// exists. The caller supplies it so the version is read from the same tree the
    10	// snapshot describes: a committed-tree snapshot must not pick up a version a
    11	// dirty working tree happens to carry.
    12	type ManifestReader func(name string) (string, bool)
    13	
    14	// ScipProjectVersionUnknown is the SCIP package version used when no manifest
    15	// declares one.
    16	//
    17	// It is "0" rather than an empty component because the field is the version of
    18	// the package, and a value that parses as one keeps the symbol honest: "0" says
    19	// "unversioned" without claiming a release. Note this is the common case for Go
    20	// repositories -- go.mod carries a module path, not a version, since Go takes
    21	// versions from Git tags -- and for tsconfig.json and setup.cfg.
    22	const ScipProjectVersionUnknown = "0"
    23	
    24	// ScipProjectVersionMaxLen bounds the declared version's LENGTH, which is a
    25	// separate concern from bounding the manifest read.
    26	//
    27	// The provider's reader caps the file, not the value pulled out of it, so a
    28	// manifest well under that cap can still declare a version of hundreds of
    29	// kilobytes -- and the version is copied into every emitted symbol, so it
    30	// amplifies. Measured: a 200 KB version across 200 symbols produced an 80 MB
    31	// index, roughly 400x. A real version is a handful of bytes; anything past this
    32	// is not one, and is treated as undeclared rather than truncated, because a
    33	// truncated version would silently name a different package.
    34	const ScipProjectVersionMaxLen = 256
    35	
    36	// scipProjectVersionManifests are the root manifests that can declare the
    37	// project's own version, in precedence order. go.mod, tsconfig.json and
    38	// setup.cfg are deliberately absent: none of them carries the version of the
    39	// project they describe.
    40	var scipProjectVersionManifests = []struct {
    41		name  string
    42		parse func(string) string
    43	}{
    44		{"package.json", parsePackageJSONVersion},
    45		{"Cargo.toml", parseCargoPackageVersion},
    46		{"pyproject.toml", parsePyProjectVersion},
    47	}
    48	
    49	// ScipProjectVersion returns the project's declared version, or "" when no
    50	// manifest declares one. It never fails: an unreadable or malformed manifest is
    51	// treated as "not declared" rather than as an error, because a version string
    52	// must not be able to fail an export.
    53	//
    54	// The version is deliberately taken from the ROOT manifest only. SCIP scopes a
    55	// package per symbol, so a monorepo whose sub-packages carry different versions
    56	// should strictly emit different packages -- but the symbol's package NAME is
    57	// the repository key here, so per-directory versions would produce the
    58	// incoherent "one package, many versions". Per-package identity is a larger
    59	// contract decision than a version lookup and is left to that decision.
    60	func ScipProjectVersion(read ManifestReader) string {
    61		if read == nil {
    62			return ""
    63		}
    64		for _, manifest := range scipProjectVersionManifests {
    65			content, ok := read(manifest.name)
    66			if !ok {
    67				continue
    68			}
    69			version := strings.TrimSpace(manifest.parse(content))
    70			if version == "" || len(version) > ScipProjectVersionMaxLen {
    71				continue
    72			}
    73			return version
    74		}
    75		return ""
    76	}
    77	
    78	func parsePackageJSONVersion(content string) string {
    79		var data struct {
    80			Version string `json:"version"`
    81		}
    82		if err := json.Unmarshal([]byte(content), &data); err != nil {
    83			return ""
    84		}
    85		return strings.TrimSpace(data.Version)
    86	}
    87	
    88	func parseCargoPackageVersion(content string) string {
    89		return tomlTableString(content, "package", "version")
    90	}
    91	
    92	func parsePyProjectVersion(content string) string {
    93		// PEP 621 first, then Poetry's pre-621 table, which is still widespread.
    94		if version := tomlTableString(content, "project", "version"); version != "" {
    95			return version
    96		}
    97		return tomlTableString(content, "tool.poetry", "version")
    98	}
    99	
   100	// tomlTableString reads a quoted string value from a top-level TOML table
   101	// without a TOML dependency, which this repository does not carry.
   102	//
   103	// It is deliberately conservative: it recognizes `key = "value"` inside the
   104	// named table and nothing else. A dynamic version, an inline table, a
   105	// multi-line string, or any shape it does not understand yields "", which the
   106	// caller reads as "not declared" and falls back from. Guessing would be worse
   107	// than falling back, because the value becomes part of every symbol's identity.
   108	func tomlTableString(content, table, key string) string {
   109		inTable := false
   110		for _, raw := range strings.Split(content, "\n") {
   111			line := strings.TrimSpace(raw)
   112			if line == "" || strings.HasPrefix(line, "#") {
   113				continue
   114			}
   115			if strings.HasPrefix(line, "[") {
   116				// A table header ends the previous table. Array-of-tables headers
   117				// ("[[bin]]") are tables too and must end it just the same.
   118				name := strings.TrimSpace(strings.Trim(line, "[]"))
   119				inTable = name == table
   120				continue
   121			}
   122			if !inTable {
   123				continue
   124			}
   125			name, value, found := strings.Cut(line, "=")
   126			if !found || strings.TrimSpace(name) != key {
   127				continue
   128			}
   129			value = strings.TrimSpace(value)
   130			// TOML has two string forms and both are ordinary in a manifest:
   131			// basic ("1.2.3") and literal ('1.2.3'). Handling only the first
   132			// exported Cargo and Python projects that use the second as version
   133			// "0", collapsing distinct releases into one package identity.
   134			for _, quote := range []string{`"`, "'"} {
   135				if !strings.HasPrefix(value, quote) {
   136					continue
   137				}
   138				// Closing quote, not a later one in a trailing comment.
   139				if end := strings.Index(value[1:], quote); end >= 0 {
   140					return value[1 : 1+end]
   141				}
   142			}
   143			return ""
   144		}
   145		return ""
   146	}
