    18	// new SCIP identity on every commit: two indexes of the same repository one
    19	// unrelated commit apart shared no symbol string at all, and nothing downstream
    20	// could match a symbol across commits. Symbol identity must depend on what the
    21	// symbol IS, not on when it was indexed.
    22	func TestSCIPSymbolIdentityIsStableAcrossCommits(t *testing.T) {
    23		record := SymbolRecord{
    24			ID:       "compound-v1:pkg/a.go:Helper",
    25			Kind:     "function",
    26			Name:     "Helper",
    27			FilePath: "a.go",
    28		}
    29		first := SnapshotHeader{RepoKey: "local/demo", Commit: "d26959da4faac2613a8827bb32472c226220bd62"}
    30		second := SnapshotHeader{RepoKey: "local/demo", Commit: "3ec3b14828324bf7dac68ba0ff6b0206ed63fbc7"}
    31	
    32		one := scipSymbol(first, "1.2.3", record)
    33		two := scipSymbol(second, "1.2.3", record)
    34		if one != two {
    35			t.Fatalf("symbol identity changed across commits:\n  %s\n  %s", one, two)
    36		}
    37		parsed, err := scippb.ParseSymbol(one)
    38		if err != nil {
    39			t.Fatalf("ParseSymbol(%q): %v", one, err)
