   738	func scipSymbol(header SnapshotHeader, projectVersion string, record SymbolRecord) string {
   739		if record.Local {
   740			// A callable defined inside another function cannot be referenced from
   741			// outside its document, and SCIP has a form that says so: `local <id>`,
   742			// scoped to the Document it appears in. Giving one a package-scoped
   743			// global symbol invites a consumer to merge two unrelated closures from
   744			// different documents that happen to share a name, or to link a
   745			// reference across a boundary the language does not have.
   746			return "local " + shortDigest(record.ID)
   747		}
   748		name := scipFirstNonEmpty(record.Name, record.QualifiedName, "symbol")
   749		return scipSymbolPrefix(header, projectVersion, record.FilePath) + scipDescriptor(name, record.Kind, shortDigest(record.ID))
   750	}
