   752	func scipDescriptor(name, kind, short string) string {
   753		if methodLikeSCIPKind(kind) {
   754			return scipIdentifier(name) + "(s" + short + ")."
   755		}
   756		descriptorName := name
   757		if !strings.Contains(descriptorName, short) {
   758			descriptorName += "$" + short
   759		}
   760		suffix := "."
   761		switch strings.ToLower(kind) {
   762		case "class", "interface", "struct", "enum", "message", "service", "trait", "type", "type_alias", "union":
   763			suffix = "#"
